from decimal import Decimal

class CartLibrary:
    ROBOT_LIBRARY_SCOPE = 'TEST'

    def __init__(self):
        self.items = []

    def add_item(self, name, price, qty='1'):
        qty = int(qty)
        if qty < 1:
            raise ValueError('qty must be at least 1')
        self.items.append((name, Decimal(price), qty))

    def cart_total_should_be(self, expected):
        total = sum((p * q for _, p, q in self.items), Decimal('0'))
        if total != Decimal(expected):
            raise AssertionError(f'Expected total {expected} but was {total}')

    def clear_cart(self):
        self.items = []
